/bin/bash -lc "node --input-type=module <<'EOF'
const base = 'http://127.0.0.1:8080';
const health = await fetch("'`${base}/health`);
if (health.status !== 200 || JSON.stringify(await health.json()) !== '"'{\"status\":\"ok\"}') throw new Error('health check failed');
const blank = await fetch("'`${base}/api/projects`, { method: '"'POST', headers: {'content-type':'application/json'}, body: JSON.stringify({name:'   '}) });
if (blank.status "'!== 400 || !(await blank.json()).error.includes('"'Project name is required')) throw new Error('blank validation failed');
const created = await fetch("'`${base}/api/projects`, { method: '"'POST', headers: {'content-type':'application/json'}, body: JSON.stringify({name:'  Sample board  '}) });
const project = await created.json();
if (created.status "'!== 201 || project.name !== '"'Sample board') throw new Error('create/trim failed');
const list = await (await fetch("'`${base}/api/projects`)).json();
if (!list.some((item) => item.id === project.id && item.name === '"'Sample board')) throw new Error('list failed');
const page = await fetch("'`${base}/projects/${project.id}`);
if (page.status !== 200 || !(await page.text()).includes('"'Workboard')) throw new Error('project route failed');
console.log('HTTP health, blank validation, trimming, listing, and project route passed');
EOF
